import json
baseline = json.load(open('baseline-packages.json'))
after = json.load(open('after-cpm-packages.json'))

def extract(data):
    result = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            key = f\"{name}|{fw['framework']}\"
            result[key] = {p['id']: p['resolvedVersion'] for p in fw['topLevelPackages']}
    return result

b = extract(baseline)
a = extract(after)

changes = []
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(key, {})
    ap = a.get(key, {})
    for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(pkg, 'N/A')
        av = ap.get(pkg, 'N/A')
        if bv != av:
            changes.append((key, pkg, bv, av))

if changes:
    print('CHANGES:')
    for c in changes:
        print(f'  {c[0]}: {c[1]} {c[2]} -> {c[3]}')
else:
    print('No changes - all versions identical')
"

